function validate([mat, k]) {
  if (!Array.isArray(mat) || mat.length < 1 || mat.length > 100) return 'mat needs 1 to 100 rows.';
  const n = Array.isArray(mat[0]) ? mat[0].length : 0;
  if (n < 1 || n > 100) return 'mat needs 1 to 100 columns.';
  for (const row of mat) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row of mat must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value of mat is an integer from 1 to 100.';
  }
  if (!Number.isInteger(k) || k < 1 || k > 100) return 'k is an integer from 1 to 100.';
  return null;
}

