function matrixBlockSum(mat, k) {
  const rows = mat.length;
  const cols = mat[0].length;
  const prefix = Array.from({ length: rows + 1 }, () => new Array(cols + 1).fill(0));

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      prefix[r + 1][c + 1] = mat[r][c] + prefix[r][c + 1] + prefix[r + 1][c] - prefix[r][c];
    }
  }

  const answer = [];
  for (let i = 0; i < rows; i++) {
    const top = Math.max(0, i - k);
    const bottom = Math.min(rows, i + k + 1);
    const row = [];
    for (let j = 0; j < cols; j++) {
      const left = Math.max(0, j - k);
      const right = Math.min(cols, j + k + 1);
      row.push(prefix[bottom][right] - prefix[top][right] - prefix[bottom][left] + prefix[top][left]);
    }
    answer.push(row);
  }
  return answer;
}

