function matrixBlockSum(mat, k) {
  const m = mat.length, n = mat[0].length;
  const out = [];
  for (let i = 0; i < m; i++) {
    out.push([]);
    for (let j = 0; j < n; j++) {
      let total = 0;
      for (let r = i - k; r <= i + k; r++)
        for (let c = j - k; c <= j + k; c++)
          if (r >= 0 && r < m && c >= 0 && c < n) total += mat[r][c];
      out[i].push(total);
    }
  }
  return out;
}

