function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const m = pick(60, 100), n = pick(60, 100);
    const k = rand() < 0.6 ? pick(1, 12) : pick(1, 100);
    const mat = Array.from({ length: m }, () => Array.from({ length: n }, () => pick(1, 100)));
    return [mat, k];
  }
  const m = pick(1, 6), n = pick(1, 6);
  const high = rand() < 0.3 ? 3 : 100;
  const mat = Array.from({ length: m }, () => Array.from({ length: n }, () => pick(1, high)));
  const k = rand() < 0.2 ? pick(1, 100) : pick(1, 4);
  return [mat, k];
}
